function processOrder(order: Order) {
  const tax = order.total * 0.08;
  const formatted = `$${(order.total + tax).toFixed(2)}`;
  if (order.type === 'online') {
    console.log('Online order', formatted);
  } else {
    console.log('In-store order', formatted);
  }
}

function buildInvoice(items: Item[]) {
  let total = 0;
  const rows: string[] = [];
  for (const it of items) {
    total += it.qty * it.price;
    rows.push(`${it.name} x${it.qty} $${(it.qty*it.price).toFixed(2)}`);
  }
  rows.push(`Total: $${total.toFixed(2)}`);
  return rows.join('\n');
}

