function applyDiscount(order: Order) {
  for (const item of order.items) {
    item.finalPrice = calculateFinalPrice(item);
  }
  // more code using finalPrice
}
function calculateFinalPrice(item: Item) {
  const discount = item.price > 100 ? item.price * 0.1 : 0;
  return +(item.price - discount).toFixed(2);
}
